# Libro 8: Crianza llena de gracia (Kimmel, Grupo Nelson). Citas verificadas en Google Books (1E3hAwAAQBAJ).
TARJ = "[sereno, cierre] "
GB = "Google Books 1E3hAwAAQBAJ (vista previa)"
C(8, 1, "Seguro, significativo y fuerte", [
 ("gancho", "marisol", "[curioso, intriga, ritmo ágil] ¿Tu hijo se siente seguro, significativo y fuerte?"),
 ("joven", "rewe", "[adolescente, casual, bajito] Yo solo quiero sentir que valgo."),
 ("idea", "marisol", "[cálido, cercano, ritmo ágil] En Crianza llena de gracia, Tim Kimmel plantea que los hijos necesitan sentirse seguros, significativos y fuertes. Y que nuestra tarea es ayudarles a cubrir esas necesidades con amor, propósito y esperanza."),
  ("cita", "marisol", "[firme, cálido, pausado] Y dice que, si cumplimos bien nuestra tarea, los hijos deberían dejar el hogar «con un amor que es seguro, un propósito que es significativo y una esperanza que es sólida»."),
 ("giro", "marisol", "[cálido, cercano, ritmo ágil] Para Kimmel, la gracia no es tanto lo que hacemos como padres, sino cómo lo hacemos. Es el tono. Es la manera."),
 ("giro2", "marisol", "[cálido, cercano, ritmo ágil] Seguro, con un amor que no se mueve. Significativo, con un propósito. Fuerte, con esperanza."),
 ("accion", "marisol", "[firme, cálido, cierre] Para hoy: elige una de las tres necesidades y pregúntate cómo se la estás cubriendo a tu hijo. Hoy, con una sola cosa concreta. Podría ser una frase como esta."),
 ("accion2", "mario", "[papá, cálido, sincero] Me da gusto que seas mi hijo. Y confío en lo que puedes hacer."),
 ("siguiente", "marisol", "[sereno, cierre] Siguiente: qué pasa cuando criamos con miedo."),
], [
 ("titular", "gancho", "seguro", "Seguro · Significativo · Fuerte", "Tres palabras que entran una por una; cada una con su color"),
 ("reaccion", "joven", "valgo", "Yo solo quiero sentir que valgo", "Burbuja del adolescente"),
 ("icono", "idea", "necesidades", "Tres necesidades de todo hijo", "Tres pilares: seguro, significativo, fuerte"),
 ("cita", "cita", "amor", "«Con un amor que es seguro, un propósito que es significativo y una esperanza que es sólida»", "Tarjeta de cita: Tim Kimmel, Crianza llena de gracia"),
 ("icono", "cita", "esperanza", "Amor · Propósito · Esperanza", "Corazón, brújula y ancla que se encienden en ese orden"),
 ("titular", "giro", "cómo", "La gracia es cómo lo haces", "«cómo» resaltado con pincelada amarilla"),
 ("icono", "giro2", "propósito", "Seguro · Significativo · Fuerte", "Tres escudos: amor, propósito, esperanza"),
 ("accion", "accion", "elige", "Para hoy: elige una de las tres", "Tarjeta «Para hoy» con tres botones y uno se enciende"),
 ("reaccion", "accion2", "confío", "Me da gusto que seas mi hijo. Y confío en lo que puedes hacer.", "Burbuja de papá en tono cálido"),
 ("titular", "siguiente", "miedo", "Siguiente: criar con miedo", "Palabra «miedo» con sombra que se encoge"),
], [GB + ", Kimmel: inventario de tres necesidades (ES p.163) y «con un amor que es seguro, un propósito que es significativo y una esperanza que es sólida» (PA26)"])

C(8, 2, "El miedo no forma", [
 ("gancho", "marisol", "[curioso, intriga, ritmo ágil] ¿Criar con miedo funciona? ¿Qué aprende un hijo ahí?"),
 ("idea", "marisol", "[cálido, cercano, ritmo ágil] Kimmel contrasta la crianza llena de gracia con varios modelos típicos de la comunidad cristiana. El primero de su lista es el más discordante: la crianza basada en el temor."),
 ("cita", "marisol", "[firme, cálido, pausado] Y es muy directo: «La crianza basada en el temor es la manera más segura de criar hijos cristianos». Y lo explica: hijos indiferentes a las cosas de Dios, o rebeldes contra sus padres, su iglesia y el Señor."),
 ("papa", "mario", "[papá, tajante, seco] En esta casa no se cuestiona."),
 ("giro", "marisol", "[cálido, cercano, ritmo ágil] Según Kimmel, en esas familias los hijos saben que su hogar es cualquier cosa menos el mejor lugar para mencionar preocupaciones sobre una religión arrogante o una espiritualidad inconsecuente."),
 ("joven", "rewe", "[adolescente, bajito, dudoso] Tengo una duda sobre Dios. Pero mejor no la digo en mi casa."),
 ("accion", "marisol", "[firme, cálido, cierre] Para hoy: si tu hijo te hace una pregunta difícil sobre la fe, agradécele que te la haya hecho. Aunque no tengas la respuesta. Sin sermón. Podrías decirle algo así."),
 ("accion2", "mario", "[papá, cálido, sincero] Gracias por preguntármelo. Si no sé la respuesta, la buscamos juntos."),
 ("siguiente", "marisol", "[sereno, cierre] Siguiente: qué hacer cuando tu hijo se equivoca."),
], [
 ("titular", "gancho", "miedo", "¿Criar con miedo funciona?", "Palabra «miedo» con una sombra grande"),
 ("icono", "idea", "temor", "Varios modelos. El primero: el temor", "Varios caminos que salen de una bifurcación; el del temor se oscurece y el de la gracia se ilumina"),
 ("cita", "cita", "temor", "«La crianza basada en el temor es la manera más segura de criar hijos cristianos...»", "Tarjeta de cita: Tim Kimmel, Crianza llena de gracia"),
 ("reaccion", "papa", "cuestiona", "En esta casa no se cuestiona", "Burbuja de papá en tono seco"),
 ("ilustracion", "giro", "hogar", "¿Dónde pueden hablar de sus dudas?", "Casa con las ventanas cerradas y luz tenue"),
 ("reaccion", "joven", "duda", "Mejor no la digo en mi casa", "Burbuja del adolescente, tenue"),
 ("accion", "accion", "pregunta", "Para hoy: agradece la pregunta difícil", "Tarjeta «Para hoy» con signo de pregunta"),
 ("reaccion", "accion2", "buscamos", "Si no sé la respuesta, la buscamos juntos", "Burbuja de papá con libro abierto"),
 ("titular", "siguiente", "equivoca", "Siguiente: cuando se equivoca", "Lápiz con goma que se levanta"),
], [GB + ", Kimmel: «La crianza basada en el temor…» (PA14)"])

C(8, 3, "Caminar con él", [
 ("gancho", "marisol", "[curioso, intriga, ritmo ágil] Tu hijo se equivocó. ¿Lo condenas, o lo acompañas?"),
 ("papa1", "mario", "[papá, molesto, tajante] ¿Cómo pudiste hacer eso?"),
 ("joven", "rewe", "[adolescente, bajito, avergonzado] Ya sé que la regué. Solo quiero que no me dejes solo."),
 ("idea", "marisol", "[cálido, cercano, ritmo ágil] En Crianza llena de gracia, Tim Kimmel escribe que una respuesta de gracia al pecado de los hijos es evitar la condena. Y que muchas veces la condena solo empeora la situación."),
 ("cita", "marisol", "[firme, cálido, pausado] Su alternativa: comprometerte a «caminar con ellos a través de su error con amor y gracia»."),
 ("giro", "marisol", "[cálido, cercano, ritmo ágil] Kimmel habla de hijos que crecen en hogares donde son libres para ser diferentes, vulnerables, ingenuos, y también para equivocarse."),
 ("papa2", "mario", "[papá, cariñoso, firme] Estoy contigo. Ya hablaremos de lo que pasó."),
 ("accion", "marisol", "[firme, cálido, cierre] Para hoy: la próxima vez que tu hijo se equivoque, dile primero que estás con él. La conversación sobre lo que pasó puede venir después. Primero, la relación."),
 ("tarjeta", "marisol", TARJ + "Crianza llena de gracia, de Tim Kimmel, de Caribe-Betania y Grupo Nelson. Este video no sustituye la lectura del libro."),
], [
 ("titular", "gancho", "acompañas", "¿Condenas o acompañas?", "Dos caminos: un dedo señalando y una mano extendida"),
 ("reaccion", "papa1", "pudiste", "¿Cómo pudiste hacer eso?", "Burbuja de papá en tono duro"),
 ("reaccion", "joven", "regué", "Ya sé que la regué. No me dejes solo.", "Burbuja del adolescente, tenue"),
 ("icono", "idea", "condena", "La condena empeora la situación", "Nube de tormenta sobre una casa pequeña"),
 ("cita", "cita", "caminar", "«Caminar con ellos a través de su error con amor y gracia»", "Tarjeta de cita: Tim Kimmel, Crianza llena de gracia"),
 ("ilustracion", "cita", "alternativa", "Dos pares de pies caminando juntos", "Huellas de dos tamaños sobre un camino"),
 ("titular", "giro", "equivocarse", "Libres para equivocarse", "Lápiz con goma; la palabra «equivocarse» se corrige y queda en pie"),
 ("reaccion", "papa2", "contigo", "Estoy contigo. Ya hablaremos de lo que pasó.", "Burbuja de papá en tono cálido"),
 ("accion", "accion", "primero", "Para hoy: primero, «estoy contigo»", "Tarjeta «Para hoy» con una mano sobre un hombro (silueta)"),
 ("tarjeta_libro", "tarjeta", "Grupo Nelson", "Crianza llena de gracia · Tim Kimmel · Caribe-Betania / Grupo Nelson", "Tarjeta de cierre estándar de la serie: portada tipográfica, sin foto; leyenda «Este video no sustituye la lectura del libro»"),
], [GB + ", Kimmel: «caminar con ellos a través de su error…» (ES p.233/PA233)"])
